/*--------------------------------------------------------------------------*/

void ecm_vtacho_rs_gwr( void )
{
	os_res_request( ecm_vtacho_vars.res , 0 );
	{
		ecm_vtacho_vars.state = ecm_vtacho_gwr;
	}
	os_res_release( ecm_vtacho_vars.res );

}

/*--------------------------------------------------------------------------*/

void ecm_vtacho_rs_ign( void )
{
	os_res_request( ecm_vtacho_vars.res , 0 );
	{
		ecm_vtacho_vars.time  = 0 ; 
        ecm_vtacho_vars.state = ecm_vtacho_ign ;	
	}
	os_res_release( ecm_vtacho_vars.res );
}

/*--------------------------------------------------------------------------*/

void ecm_vtacho_rs_start( void )
{
	os_res_request( ecm_vtacho_vars.res , 0 );
	{
		ecm_vtacho_vars.state = ecm_vtacho_start;	
	}
	os_res_release( ecm_vtacho_vars.res );
}

